DO $$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('public.personal_home()'::regprocedure); definition:=replace(definition,'ORDER BY updated_at DESC,id LIMIT 1','ORDER BY created_at DESC,id LIMIT 1'); EXECUTE definition; definition:=pg_get_functiondef('public.walk_in_admit(uuid,uuid,text,text,text,text,text)'::regprocedure); definition:=replace(definition,'SELECT id INTO uid FROM profiles WHERE em IS NOT NULL AND lower(email)=em LIMIT 1;','SELECT id INTO uid FROM auth.users WHERE em IS NOT NULL AND lower(email)=em LIMIT 1;'); EXECUTE definition; END $$;